23 | contract OptimisticListingSeaport is
24 |     IOptimisticListingSeaport,
25 |     Module,
26 |     Multicall,
27 |     NFTReceiver,
28 |     SafeSend,
29 |     SelfPermit
30 | {
31 |     /// @notice Address of VaultRegistry contract
32 |     address public immutable registry;
33 |     /// @notice Address of the Seaport contract
34 |     address public immutable seaport;
35 |     /// @notice Address of the Zone to list items under
36 |     address public immutable zone;
37 |     /// @notice The conduit key used to deploy the conduit
38 |     bytes32 public immutable conduitKey;
39 |     /// @notice Address of Supply target contract
40 |     address public immutable supply;
41 |     /// @notice Address of the SeaportLister target contract
42 |     address public immutable seaportLister;
43 |     /// @notice Time period of a proposed listing
44 |     uint256 public immutable PROPOSAL_PERIOD;
45 |     /// @notice Address of the OpenSea recipient for receiving fees
46 |     address payable public immutable OPENSEA_RECIPIENT;
47 |     /// @notice Address of the protocol fee receiver
48 |     address payable public feeReceiver;
49 |     /// @notice Mapping of vault address to order hash
50 |     mapping(address => bytes32) public vaultOrderHash;
51 |     /// @notice Mapping of vault address to active listings on Seaport
52 |     mapping(address => Listing) public activeListings;
53 |     /// @notice Mapping of vault address to newly proposed listings
54 |     mapping(address => Listing) public proposedListings;
55 |     /// @notice Mapping of vault address to user address to collateral amount
56 |     mapping(address => mapping(address => uint256)) public pendingBalances;
57 | 
58 |     /// @dev Initializes contract state
59 |     constructor(
60 |         address _registry,
61 |         address _seaport,
62 |         address _zone,
63 |         bytes32 _conduitKey,
64 |         address _supply,
65 |         address _seaportLister,
66 |         address payable _feeReceiver,
67 |         address payable _openseaRecipient,
68 |         uint256 _proposalPeriod,
69 |         address payable _weth
70 |     ) SafeSend(_weth) {
71 |         registry = _registry;
72 |         seaport = _seaport;
73 |         zone = _zone;
74 |         conduitKey = _conduitKey;
75 |         supply = _supply;
76 |         seaportLister = _seaportLister;
77 |         feeReceiver = _feeReceiver;
78 |         OPENSEA_RECIPIENT = _openseaRecipient;
79 |         PROPOSAL_PERIOD = _proposalPeriod;
80 |     }
81 | 
82 |     /// @dev Callback for receiving ether when the calldata is empty
83 |     receive() external payable {}
